-- public.bite_weight(p_fish text, p_weight double precision, p_bait text, p_mul jsonb)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.bite_weight(p_fish text, p_weight double precision, p_bait text, p_mul jsonb DEFAULT NULL::jsonb)
 RETURNS double precision
 LANGUAGE sql
 STABLE
AS $function$
  select p_weight * pk(p_mul, 'bite:' || p_fish, 1) * case
    when p_bait is null or not exists (select 1 from bait_def b where b.id = p_bait) then 1
    else coalesce((select (bait_pull() * pk(p_mul, 'bait:pull', 1)) / (bf.rank + 1) from bait_favours bf
                    where bf.bait = p_bait and bf.fish = p_fish), bait_shy())
    end
$function$
